/**
 * Skin micro-detail (Part 2 F19): tileable pore and stubble-hair patterns,
 * laid over the skin in a layer masked per region (procedural.ts draws the
 * region strength for 'pores' and 'stubbleHair').
 *
 * The PRD asks for CC0 sources. Poly Haven and ambientCG have no skin
 * textures, and ShareTextures' "human skin" set is under its own CC0-based
 * licence that forbids redistribution in other products, so it cannot ship
 * here (DECISIONS.md). The tiles are therefore generated by this code, PS2CC's
 * own and CC0 like the rest of the generated art, and no file is shipped.
 *
 * The tile is sampled at the composite's resolution (the GPU compositor
 * draws it per output texel, also straight into the head texture), not at
 * the 1024 px the procedural layers are drawn at: pores are ~1 mm apart,
 * a few texels of the face at 2048. Tiles are periodic in both directions,
 * and sampled with wrap-around on the CPU (sampleWrap) and REPEAT on the GPU.
 */
import { hash3 } from './noise';
import type { RgbaImage } from './image';
import type { SkinLayout } from './layout';

export type DetailPattern = 'pores' | 'stubbleHair';

/** Tile size in texels; small enough to need no mipmaps at the face's texel density. */
export const DETAIL_TILE_SIZE = 128;

/** How much skin one tile covers (metres) at scale 1: 32 pores across, ~1 mm apart. */
export const DETAIL_TILE_METRES: Record<DetailPattern, number> = { pores: 0.03, stubbleHair: 0.024 };

const tiles = new Map<string, RgbaImage>();

/**
 * The tile of a pattern. Pores: grey 128 (neutral in overlay) with darker pits
 * and faint ridges between them. Stubble hairs: white (neutral in multiply)
 * with short slanted hair stubs in `hair` colour.
 */
export function detailTile(pattern: DetailPattern, hair: [number, number, number] = [60, 45, 35]): RgbaImage {
  const key = `${pattern}:${hair.join(',')}`;
  let tile = tiles.get(key);
  if (!tile) {
    tile = pattern === 'pores' ? poresTile() : stubbleTile(hair);
    tiles.set(key, tile);
  }
  return tile;
}

/** Signed periodic offset from b to a on a ring of length n (shortest way round). */
function wrapDelta(a: number, b: number, n: number): number {
  let d = a - b;
  d -= Math.round(d / n) * n;
  return d;
}

function poresTile(): RgbaImage {
  const n = DETAIL_TILE_SIZE;
  const cells = 32;
  const cell = n / cells;
  const value = new Float32Array(n * n);
  // One pore per cell, jittered, with its own depth and size (periodic: cells wrap).
  const pores: { x: number; y: number; r: number; depth: number }[] = [];
  for (let cy = 0; cy < cells; cy++)
    for (let cx = 0; cx < cells; cx++) {
      const h = (k: number) => hash3(cx, cy, k, 4111);
      pores.push({ x: (cx + 0.15 + 0.7 * h(1)) * cell, y: (cy + 0.15 + 0.7 * h(2)) * cell, r: 0.55 + 0.6 * h(3), depth: 0.35 + 0.65 * h(4) });
    }
  for (let y = 0; y < n; y++)
    for (let x = 0; x < n; x++) {
      const px = x + 0.5;
      const py = y + 0.5;
      const cx = Math.floor(px / cell);
      const cy = Math.floor(py / cell);
      let pit = 0;
      let nearest = Infinity;
      let second = Infinity;
      for (let dy = -1; dy <= 1; dy++)
        for (let dx = -1; dx <= 1; dx++) {
          const p = pores[((cy + dy + cells) % cells) * cells + ((cx + dx + cells) % cells)]!;
          const ddx = wrapDelta(px, p.x, n);
          const ddy = wrapDelta(py, p.y, n);
          const d2 = ddx * ddx + ddy * ddy;
          pit = Math.max(pit, p.depth * Math.exp(-d2 / (p.r * p.r)));
          const d = Math.sqrt(d2);
          if (d < nearest) [second, nearest] = [nearest, d];
          else if (d < second) second = d;
        }
      // Ridges: the skin between pores sits a touch higher (lighter) away from the cell borders.
      const ridge = Math.min(1, (second - nearest) / cell);
      value[y * n + x] = -pit + 0.12 * ridge;
    }
  // Fine crossing creases (skin's diamond micro-relief): two periodic families of faint lines.
  for (let y = 0; y < n; y++)
    for (let x = 0; x < n; x++) {
      const a = Math.sin(((x + y * 0.5) / n) * Math.PI * 2 * 22 + 1.3 * Math.sin((y / n) * Math.PI * 2 * 3));
      const b = Math.sin(((x - y * 0.6) / n) * Math.PI * 2 * 18 + 1.1 * Math.sin((x / n) * Math.PI * 2 * 2));
      value[y * n + x] = value[y * n + x]! - 0.06 * Math.max(0, a) ** 8 - 0.05 * Math.max(0, b) ** 8;
    }
  const data = new Uint8ClampedArray(n * n * 4);
  for (let i = 0; i < n * n; i++) {
    const g = Math.round(128 + 110 * value[i]!);
    data[i * 4] = g;
    data[i * 4 + 1] = Math.round(g * 0.985);
    data[i * 4 + 2] = Math.round(g * 0.97);
    data[i * 4 + 3] = 255;
  }
  return { width: n, height: n, data };
}

function stubbleTile(hair: [number, number, number]): RgbaImage {
  const n = DETAIL_TILE_SIZE;
  const cells = 24;
  const cell = n / cells;
  const cover = new Float32Array(n * n);
  // One stub per cell: a short line slanting down and outwards (beard growth), ~1 texel wide.
  for (let cy = 0; cy < cells; cy++)
    for (let cx = 0; cx < cells; cx++) {
      const h = (k: number) => hash3(cx, cy, k, 7307);
      const x0 = (cx + h(1)) * cell;
      const y0 = (cy + h(2)) * cell;
      const len = 1.5 + 2.5 * h(3);
      const ang = Math.PI / 2 + (h(4) - 0.5) * 1.2;
      const dark = 0.55 + 0.45 * h(5);
      const steps = Math.ceil(len * 3);
      for (let s = 0; s <= steps; s++) {
        const t = s / steps;
        const px = x0 + Math.cos(ang) * len * t;
        const py = y0 + Math.sin(ang) * len * t;
        // Splat into the 2x2 texels around the point (periodic).
        const fx = px - 0.5;
        const fy = py - 0.5;
        const ix = Math.floor(fx);
        const iy = Math.floor(fy);
        const tx = fx - ix;
        const ty = fy - iy;
        const taper = dark * (1 - 0.5 * t);
        for (const [ox, oy, w] of [[0, 0, (1 - tx) * (1 - ty)], [1, 0, tx * (1 - ty)], [0, 1, (1 - tx) * ty], [1, 1, tx * ty]] as const) {
          const i = (((iy + oy) % n) + n) % n * n + ((((ix + ox) % n) + n) % n);
          cover[i] = Math.max(cover[i]!, taper * w * 1.6);
        }
      }
    }
  const data = new Uint8ClampedArray(n * n * 4);
  for (let i = 0; i < n * n; i++) {
    const c = Math.min(1, cover[i]!);
    for (let k = 0; k < 3; k++) data[i * 4 + k] = Math.round(255 + (hair[k]! - 255) * c);
    data[i * 4 + 3] = 255;
  }
  return { width: n, height: n, data };
}

/** Bilinear sample with wrap-around (GL REPEAT + LINEAR); same row convention as sampleBilinear (v = 1 at row 0). */
export function sampleWrap(img: RgbaImage, u: number, v: number, out: Float32Array | number[]): void {
  const w = img.width;
  const h = img.height;
  const fx = u * w - 0.5;
  const fy = (1 - v) * h - 0.5;
  const x0 = Math.floor(fx);
  const y0 = Math.floor(fy);
  const tx = fx - x0;
  const ty = fy - y0;
  const wx0 = ((x0 % w) + w) % w;
  const wx1 = (wx0 + 1) % w;
  const wy0 = ((y0 % h) + h) % h;
  const wy1 = (wy0 + 1) % h;
  const d = img.data;
  const i00 = (wy0 * w + wx0) * 4;
  const i10 = (wy0 * w + wx1) * 4;
  const i01 = (wy1 * w + wx0) * 4;
  const i11 = (wy1 * w + wx1) * 4;
  for (let k = 0; k < 4; k++) {
    const top = d[i00 + k]! + (d[i10 + k]! - d[i00 + k]!) * tx;
    const bottom = d[i01 + k]! + (d[i11 + k]! - d[i01 + k]!) * tx;
    out[k] = top + (bottom - top) * ty;
  }
}

/**
 * UV units per metre on the face (the largest head island) of the neutral
 * mesh: sqrt(UV area / surface area). A tile of `metres` then repeats
 * 1 / (uvPerMetre * metres) times across the UV square.
 */
export function faceUvPerMetre(layout: SkinLayout): number {
  const face = layout.islands.filter((i) => i.kind === 'head').sort((a, b) => b.faces.length - a.faces.length)[0]!.id;
  const pos = layout.base.positions;
  const uv = layout.base.uvs;
  let uvArea = 0;
  let area = 0;
  for (const t of layout.trianglesOf((i) => i.id === face)) {
    const [a, b, c] = t.verts;
    const e1 = [0, 1, 2].map((k) => pos[b * 3 + k]! - pos[a * 3 + k]!);
    const e2 = [0, 1, 2].map((k) => pos[c * 3 + k]! - pos[a * 3 + k]!);
    area += 0.5 * Math.hypot(e1[1]! * e2[2]! - e1[2]! * e2[1]!, e1[2]! * e2[0]! - e1[0]! * e2[2]!, e1[0]! * e2[1]! - e1[1]! * e2[0]!);
    const [p, q, r] = t.uvs;
    uvArea += 0.5 * Math.abs((uv[q * 2]! - uv[p * 2]!) * (uv[r * 2 + 1]! - uv[p * 2 + 1]!) - (uv[r * 2]! - uv[p * 2]!) * (uv[q * 2 + 1]! - uv[p * 2 + 1]!));
  }
  return Math.sqrt(uvArea / area);
}
